query:
-- Citrus hystrix : Combava (fruit zeste) vs Combava Feuille
UPDATE plants SET plant_part = 'zeste' WHERE id = 660755 AND name LIKE '%Combava%' AND notes LIKE '%fruit%';
UPDATE plants SET plant_part = 'feuille' WHERE id = 690117 AND notes LIKE '%feuille%';

-- Citrus aurantium : Bigaradier (fruit/écorce) vs Néroli (fleur)
UPDATE plants SET plant_part = 'zeste' WHERE id = 420001 AND notes LIKE '%fruit%';
UPDATE plants SET plant_part = 'fleur' WHERE id = 690175 AND notes LIKE '%fleur%';

-- Myristica fragrans : Muscade (graine) vs Macis (arille)
UPDATE plants SET plant_part = 'graine' WHERE latin_name = 'Myristica fragrans' AND (name LIKE '%Muscade%' OR name LIKE '%Noix%');
UPDATE plants SET plant_part = 'arille' WHERE latin_name = 'Myristica fragrans' AND name LIKE '%Macis%';

-- Vetiveria zizanioides : racine
UPDATE plants SET plant_part = 'racine' WHERE latin_name LIKE '%Vetiveria%' OR latin_name LIKE '%Chrysopogon zizanioides%';

-- Syzygium aromaticum : clou (bouton floral) vs feuille
UPDATE plants SET plant_part = 'fleur' WHERE latin_name = 'Syzygium aromaticum' AND (name LIKE '%Clou%' OR name LIKE '%Girofle%') AND name NOT LIKE '%feuille%' AND name NOT LIKE '%tige%';
UPDATE plants SET plant_part = 'feuille' WHERE latin_name = 'Syzygium aromaticum' AND name LIKE '%feuille%';
UPDATE plants SET plant_part = 'feuille_tige' WHERE latin_name = 'Syzygium aromaticum' AND name LIKE '%tige%';

-- Evernia prunastri : thalle (lichen)
UPDATE plants SET plant_part = 'thalle' WHERE latin_name = 'Evernia prunastri';

-- Boswellia sacra : résine
UPDATE plants SET plant_part = 'resine' WHERE latin_name LIKE 'Boswellia%';

-- Cinnamomum : écorce vs feuille
UPDATE plants SET plant_part = 'ecorce' WHERE latin_name LIKE 'Cinnamomum%' AND (name LIKE '%Cannelle%' OR name LIKE '%Cannelier%') AND name NOT LIKE '%feuille%';
UPDATE plants SET plant_part = 'feuille' WHERE latin_name LIKE 'Cinnamomum%' AND name LIKE '%feuille%';

SELECT id, name, latin_name, plant_part FROM plants WHERE plant_part IS NOT NULL ORDER BY latin_name LIMIT 30;

